CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "Role" AS ENUM ('ADMIN','MANAGER','EMPLOYEE');
CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "EmploymentStatus" AS ENUM ('ACTIVE','ON_LEAVE','RESIGNED','TERMINATED');
CREATE TYPE "WorkMode" AS ENUM ('WFO','WFH');
CREATE TYPE "AttendanceStatus" AS ENUM ('PRESENT','LATE','ABSENT','ON_LEAVE','HOLIDAY','WEEKLY_OFF','INCOMPLETE','EARLY_LOGOUT','PRESENT_WITH_INSUFFICIENT_HOURS');
CREATE TYPE "TaskPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TYPE "TaskStatus" AS ENUM ('BACKLOG','TODO','IN_PROGRESS','ON_HOLD','REVIEW','COMPLETED','CANCELLED');
CREATE TYPE "ProjectStatus" AS ENUM ('ACTIVE','COMPLETED','ON_HOLD','ARCHIVED');
CREATE TYPE "LeaveStatus" AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED');
CREATE TYPE "EventType" AS ENUM ('LOGIN','LOGOUT','BREAK_START','BREAK_END','IDLE_START','IDLE_END','TASK_START','TASK_PAUSE','TASK_RESUME','TASK_STOP','TASK_COMPLETED');
CREATE TABLE "User"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"accountStatus" "AccountStatus" NOT NULL DEFAULT 'ACTIVE',"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Department"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"name" TEXT NOT NULL UNIQUE,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Employee"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"userId" TEXT NOT NULL UNIQUE,"employeeId" TEXT NOT NULL UNIQUE,"fullName" TEXT NOT NULL,"profilePhoto" TEXT,"phone" TEXT,"dateOfJoining" TIMESTAMP(3) NOT NULL,"designation" TEXT NOT NULL,"departmentId" TEXT NOT NULL,"managerId" TEXT,"employmentStatus" "EmploymentStatus" NOT NULL DEFAULT 'ACTIVE',"workModeEligibility" TEXT NOT NULL DEFAULT 'WFO,WFH',"standardWorkingMinutes" INTEGER NOT NULL DEFAULT 480,"shift" TEXT,"officeLocation" TEXT,"accountStatus" "AccountStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Attendance"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"workMode" "WorkMode" NOT NULL,"status" "AttendanceStatus" NOT NULL DEFAULT 'INCOMPLETE',"scheduledStart" TIMESTAMP(3) NOT NULL,"scheduledEnd" TIMESTAMP(3) NOT NULL,"loginTime" TIMESTAMP(3),"logoutTime" TIMESTAMP(3),"requiredMinutes" INTEGER NOT NULL,"loggedInMinutes" INTEGER NOT NULL DEFAULT 0,"activeMinutes" INTEGER NOT NULL DEFAULT 0,"idleMinutes" INTEGER NOT NULL DEFAULT 0,"breakMinutes" INTEGER NOT NULL DEFAULT 0,"taskMinutes" INTEGER NOT NULL DEFAULT 0,"shortageMinutes" INTEGER NOT NULL DEFAULT 0,"overtimeMinutes" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("employeeId","date"));
CREATE TABLE "WorkSession"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"attendanceId" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3));
CREATE TABLE "BreakSession"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"attendanceId" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3));
CREATE TABLE "IdleSession"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"attendanceId" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3));
CREATE TABLE "WorkEvent"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"attendanceId" TEXT NOT NULL,"type" "EventType" NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"metadata" JSONB);
CREATE TABLE "Project"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"name" TEXT NOT NULL UNIQUE,"description" TEXT,"status" "ProjectStatus" NOT NULL DEFAULT 'ACTIVE',"startDate" TIMESTAMP(3),"endDate" TIMESTAMP(3),"managerId" TEXT NOT NULL,"departmentId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Task"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"taskNumber" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"description" TEXT,"projectId" TEXT,"assignedToId" TEXT NOT NULL,"assignedById" TEXT NOT NULL,"priority" "TaskPriority" NOT NULL DEFAULT 'MEDIUM',"status" "TaskStatus" NOT NULL DEFAULT 'TODO',"startDate" TIMESTAMP(3),"dueDate" TIMESTAMP(3),"estimatedMinutes" INTEGER,"actualMinutes" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3));
CREATE TABLE "TaskTimerSession"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"taskId" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3));
CREATE TABLE "TaskComment"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"taskId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"message" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LeaveType"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"name" TEXT NOT NULL UNIQUE,"description" TEXT);
CREATE TABLE "LeaveRequest"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"employeeId" TEXT NOT NULL,"leaveTypeId" TEXT NOT NULL,"fromDate" TIMESTAMP(3) NOT NULL,"toDate" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"halfDay" BOOLEAN NOT NULL DEFAULT false,"status" "LeaveStatus" NOT NULL DEFAULT 'PENDING',"reviewedById" TEXT,"reviewedAt" TIMESTAMP(3),"reviewComment" TEXT);
CREATE TABLE "Holiday"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"name" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL UNIQUE,"description" TEXT);
CREATE TABLE "Notification"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"recipientId" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CompanySetting"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"companyName" TEXT NOT NULL DEFAULT 'Employee Work Management System',"timezone" TEXT NOT NULL DEFAULT 'Asia/Kolkata',"currency" TEXT NOT NULL DEFAULT 'INR',"workingDays" JSONB NOT NULL,"startTime" TEXT NOT NULL DEFAULT '09:30',"endTime" TEXT NOT NULL DEFAULT '18:30',"requiredMinutes" INTEGER NOT NULL DEFAULT 480,"gracePeriodMinutes" INTEGER NOT NULL DEFAULT 10,"breakLimitMinutes" INTEGER NOT NULL DEFAULT 60,"breakWarningThresholdMinutes" INTEGER NOT NULL DEFAULT 50,"idleThresholdMinutes" INTEGER NOT NULL DEFAULT 5,"idleWarningSeconds" INTEGER NOT NULL DEFAULT 60,"maximumSessionDurationMinutes" INTEGER NOT NULL DEFAULT 720,"allowWFH" BOOLEAN NOT NULL DEFAULT true,"allowWFO" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog"("id" TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,"actorId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"oldValue" JSONB,"newValue" JSONB,"timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ip" TEXT);
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_departmentId_fkey" FOREIGN KEY("departmentId") REFERENCES "Department"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_managerId_fkey" FOREIGN KEY("managerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Attendance" ADD CONSTRAINT "Attendance_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkSession" ADD CONSTRAINT "WorkSession_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkSession" ADD CONSTRAINT "WorkSession_attendanceId_fkey" FOREIGN KEY("attendanceId") REFERENCES "Attendance"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BreakSession" ADD CONSTRAINT "BreakSession_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BreakSession" ADD CONSTRAINT "BreakSession_attendanceId_fkey" FOREIGN KEY("attendanceId") REFERENCES "Attendance"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IdleSession" ADD CONSTRAINT "IdleSession_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IdleSession" ADD CONSTRAINT "IdleSession_attendanceId_fkey" FOREIGN KEY("attendanceId") REFERENCES "Attendance"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkEvent" ADD CONSTRAINT "WorkEvent_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkEvent" ADD CONSTRAINT "WorkEvent_attendanceId_fkey" FOREIGN KEY("attendanceId") REFERENCES "Attendance"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Project" ADD CONSTRAINT "Project_managerId_fkey" FOREIGN KEY("managerId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Project" ADD CONSTRAINT "Project_departmentId_fkey" FOREIGN KEY("departmentId") REFERENCES "Department"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_assignedToId_fkey" FOREIGN KEY("assignedToId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_assignedById_fkey" FOREIGN KEY("assignedById") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TaskTimerSession" ADD CONSTRAINT "TaskTimerSession_taskId_fkey" FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TaskTimerSession" ADD CONSTRAINT "TaskTimerSession_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TaskComment" ADD CONSTRAINT "TaskComment_taskId_fkey" FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TaskComment" ADD CONSTRAINT "TaskComment_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_leaveTypeId_fkey" FOREIGN KEY("leaveTypeId") REFERENCES "LeaveType"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_recipientId_fkey" FOREIGN KEY("recipientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE INDEX "Employee_departmentId_idx" ON "Employee"("departmentId"); CREATE INDEX "Employee_managerId_idx" ON "Employee"("managerId"); CREATE INDEX "Attendance_date_idx" ON "Attendance"("date"); CREATE INDEX "Attendance_status_idx" ON "Attendance"("status"); CREATE INDEX "WorkSession_employeeId_startedAt_idx" ON "WorkSession"("employeeId","startedAt"); CREATE INDEX "BreakSession_employeeId_startedAt_idx" ON "BreakSession"("employeeId","startedAt"); CREATE INDEX "IdleSession_employeeId_startedAt_idx" ON "IdleSession"("employeeId","startedAt"); CREATE INDEX "WorkEvent_employeeId_occurredAt_idx" ON "WorkEvent"("employeeId","occurredAt"); CREATE INDEX "Task_assignedToId_status_idx" ON "Task"("assignedToId","status"); CREATE INDEX "Task_projectId_idx" ON "Task"("projectId"); CREATE INDEX "TaskTimerSession_employeeId_endedAt_idx" ON "TaskTimerSession"("employeeId","endedAt"); CREATE INDEX "TaskComment_taskId_idx" ON "TaskComment"("taskId"); CREATE INDEX "LeaveRequest_employeeId_fromDate_idx" ON "LeaveRequest"("employeeId","fromDate"); CREATE INDEX "Notification_recipientId_read_createdAt_idx" ON "Notification"("recipientId","read","createdAt"); CREATE INDEX "AuditLog_entity_entityId_idx" ON "AuditLog"("entity","entityId"); CREATE INDEX "AuditLog_timestamp_idx" ON "AuditLog"("timestamp");
